begin;
set local role service_role;
do $verify$
declare p jsonb; q jsonb; op jsonb; same_op jsonb; changed jsonb; link jsonb; legacy jsonb; refused jsonb; armed jsonb; blocked jsonb; third jsonb; result boolean; count_rows integer; previous_status text; link_op jsonb; resumed jsonb;
begin
  if has_table_privilege('anon','public.slack_task_operations','select') or has_function_privilege('authenticated','public.reserve_slack_operation(text,uuid,integer,uuid,text,text,jsonb)','execute') then raise exception 'public recovery privilege'; end if;
  p := '{"id":"11111111-1111-5111-8111-111111111111","revision":1,"status":"pending","reviewerSlackId":"UMAYA","teamId":"TONE","suggestion":{"t":"Raise quota","a":"UMAYA","p":"DB","c":"CONE","ts":"1.1","s":"Private source","th":"1.0"}}'::jsonb;
  q := p || '{"id":"22222222-2222-5222-8222-222222222222","suggestion":{"t":"Raise quota","a":"UMAYA","p":"DB","c":"CTWO","ts":"2.1","s":"Another source"}}'::jsonb;
  if not public.save_slack_proposal('verify-org',p) or not public.save_slack_proposal('verify-org',q) then raise exception 'proposal insert failed'; end if;
  changed := p || '{"revision":2,"status":"dismissed"}'::jsonb;
  if public.save_slack_proposal('verify-org',changed,2) then raise exception 'stale revision accepted'; end if;
  changed := p || '{"revision":2,"suggestion":{"t":"Raise quota","a":"UMAYA","p":"DB","c":"CONE","ts":"1.1","s":"Changed evidence","th":"1.0"}}'::jsonb;
  if public.save_slack_proposal('verify-org',changed,1) then raise exception 'source mutation accepted'; end if;
  op := public.reserve_slack_operation('verify-org',(p->>'id')::uuid,1,'33333333-3333-5333-8333-333333333333','exact-title','UMAYA');
  same_op := public.reserve_slack_operation('verify-org',(q->>'id')::uuid,1,'44444444-4444-5444-8444-444444444444','exact-title','UMAYA');
  if op->>'id' <> same_op->>'id' then raise exception 'duplicate exact reservation'; end if;
  select status into previous_status from public.slack_task_proposals where org_id='verify-org' and id=(q->>'id')::uuid;
  if previous_status<>'pending' then raise exception 'distinct source implicitly linked'; end if;
  if public.save_slack_proposal('verify-org',p || '{"revision":2,"status":"dismissed"}'::jsonb,1) then raise exception 'reserved proposal was editable'; end if;
  op := public.advance_slack_operation('verify-org',(op->>'id')::uuid,'reserved','{"state":"creating"}');
  if public.advance_slack_operation('verify-org',(op->>'id')::uuid,'reserved','{"state":"creating"}') is not null then raise exception 'operation compare-and-swap failed'; end if;
  op := public.advance_slack_operation('verify-org',(op->>'id')::uuid,'creating','{"state":"remote_succeeded","issueKey":"DB-1","issueUrl":"https://x.atlassian.net/browse/DB-1"}');
  if op->>'issueKey'<>'DB-1' then raise exception 'remote identity was lost'; end if;
  if public.save_slack_proposal('verify-org',p || '{"revision":2,"status":"dismissed"}'::jsonb,1) then raise exception 'successful action was dismissed'; end if;
  changed := public.complete_slack_proposal('verify-org',(p->>'id')::uuid,1,(op->>'id')::uuid,'exact-title','UMAYA','2026-10-05T12:00:00Z');
  if changed->>'status'<>'created' then raise exception 'created lifecycle save failed'; end if;
  link_op := public.reserve_slack_link_operation('verify-org',(q->>'id')::uuid,1,'23232323-2323-5232-8232-232323232323','exact-title','UMAYA','{"key":"DB-2","url":"https://x.atlassian.net/browse/DB-2"}');
  if link_op->>'issueKey'<>'DB-2' or link_op->>'kind'<>'link' then raise exception 'explicit different issue link was collapsed'; end if;
  if public.save_slack_proposal('verify-org',q || '{"revision":2,"status":"dismissed"}'::jsonb,1) then raise exception 'partial link result was editable'; end if;
  resumed := public.reserve_slack_operation('verify-org',(q->>'id')::uuid,1,'24242424-2424-5242-8242-242424242424','exact-title','UMAYA');
  if resumed->>'id'<>link_op->>'id' then raise exception 'link-only retry armed creation'; end if;
  if public.advance_slack_operation('verify-org',(link_op->>'id')::uuid,'remote_succeeded','{"state":"creating"}') is not null then raise exception 'link-only operation entered creating'; end if;
  if public.reserve_slack_link_operation('verify-org',(q->>'id')::uuid,1,'25252525-2525-5252-8252-252525252525','exact-title','UMAYA','{"key":"DB-3","url":"https://x.atlassian.net/browse/DB-3"}') is not null then raise exception 'partial link target changed'; end if;
  perform public.advance_slack_operation('verify-org',(link_op->>'id')::uuid,'remote_succeeded','{"state":"linked"}');
  changed := public.complete_slack_proposal('verify-org',(q->>'id')::uuid,1,(link_op->>'id')::uuid,'exact-title','UMAYA','2026-10-05T12:00:00Z');
  if changed->>'status'<>'linked' or changed->>'issueKey'<>'DB-2' then raise exception 'link-only finalization lost selected issue'; end if;
  select count(*) into count_rows from public.slack_task_operations where org_id='verify-org' and fingerprint='exact-title';
  if count_rows<>1 then raise exception 'link path altered shared create reservation'; end if;
  insert into public.slack_task_links(org_id,project,fingerprint,title_fingerprint,title,tokens,issue_key,issue_url,assignee_slack_id,tracked_by,channel,message_ts)
    values ('verify-org','DB','source-one','exact-title','Raise quota',array['raise','quota'],'DB-1','https://x.atlassian.net/browse/DB-1','UMAYA','UMAYA','CONE','1.1');
  perform public.record_slack_task_repeat('verify-org','DB','source-one','CTWO','2.1');
  perform public.record_slack_task_repeat('verify-org','DB','source-one','CTWO','2.1');
  select mention_count into count_rows from public.slack_task_links where org_id='verify-org' and fingerprint='source-one' and channel='CONE' and message_ts='1.1';
  if count_rows<>2 then raise exception 'repeat count or origin changed'; end if;
  link := '{"project":"DB","fingerprint":"source-one","issueKey":"DB-1","channel":"CONE","messageTs":"1.1"}'::jsonb;
  perform public.observe_slack_completion('verify-org',link,'{"statusCategory":"new","providerVersion":"1"}','55555555-5555-5555-8555-555555555555');
  perform public.observe_slack_completion('verify-org',link,'{"statusCategory":"done","providerVersion":"2"}','55555555-5555-5555-8555-555555555555');
  perform public.observe_slack_completion('verify-org',link,'{"statusCategory":"done","providerVersion":"2"}','66666666-6666-5666-8666-666666666666');
  select count(*) into count_rows from public.slack_completion_feedback where org_id='verify-org';
  if count_rows<>1 then raise exception 'duplicate completion delivery'; end if;
  op := public.advance_slack_feedback('verify-org','55555555-5555-5555-8555-555555555555','pending','{"state":"sending"}');
  if op->>'state'<>'sending' or public.advance_slack_feedback('verify-org','55555555-5555-5555-8555-555555555555','pending','{"state":"sending"}') is not null then raise exception 'feedback compare-and-swap failed'; end if;
  if public.save_slack_proposal('other-org',p || '{"revision":3}'::jsonb,2) then raise exception 'cross-org proposal read'; end if;
  legacy := p || '{"id":"77777777-7777-5777-8777-777777777777","suggestion":{"t":"Legacy quota","a":"UMAYA","p":"DB","c":"CLEGACY","ts":"3.1","s":"Legacy source"}}'::jsonb;
  perform public.save_slack_proposal('verify-org',legacy);
  insert into public.slack_claims(org_id,key) values ('verify-org','track:CLEGACY:3.1');
  op := public.reserve_slack_operation('verify-org',(legacy->>'id')::uuid,1,'88888888-8888-5888-8888-888888888888','legacy-title','UMAYA');
  if op->>'state'<>'uncertain' then raise exception 'legacy unknown write was retried'; end if;
  refused := p || '{"id":"99999999-9999-5999-8999-999999999999","suggestion":{"t":"Refused quota","a":"UMAYA","p":"DB","c":"CREFUSED","ts":"4.1","s":"Refused source"}}'::jsonb;
  perform public.save_slack_proposal('verify-org',refused);
  op := public.reserve_slack_operation('verify-org',(refused->>'id')::uuid,1,'aaaaaaaa-aaaa-5aaa-8aaa-aaaaaaaaaaaa','refused-title','UMAYA');
  perform public.advance_slack_operation('verify-org',(op->>'id')::uuid,'reserved','{"state":"refused"}');
  refused := refused || '{"revision":2,"suggestion":{"t":"Revised quota","a":"UMAYA","p":"DB","c":"CREFUSED","ts":"4.1","s":"Refused source"}}'::jsonb;
  if not public.save_slack_proposal('verify-org',refused,1) then raise exception 'definite refusal blocked revision'; end if;
  op := public.reserve_slack_operation('verify-org',(refused->>'id')::uuid,2,'bbbbbbbb-bbbb-5bbb-8bbb-bbbbbbbbbbbb','revised-title','UMAYA');
  if op->>'state'<>'reserved' or op#>>'{proposal,suggestion,t}'<>'Revised quota' then raise exception 'revised approved payload was stale'; end if;
  armed := p || '{"id":"cccccccc-cccc-5ccc-8ccc-cccccccccccc","suggestion":{"t":"Overlapping quota","a":"UMAYA","p":"DB","c":"CARMED","ts":"5.1","s":"Armed source"}}'::jsonb;
  blocked := p || '{"id":"dddddddd-dddd-5ddd-8ddd-dddddddddddd","suggestion":{"t":"Overlapping quota","a":"UMAYA","p":"DB","c":"CBLOCKED","ts":"6.1","s":"Blocked source"}}'::jsonb;
  third := p || '{"id":"eeeeeeee-eeee-5eee-8eee-eeeeeeeeeeee","suggestion":{"t":"Overlapping quota","a":"UMAYA","p":"DB","c":"CTHIRD","ts":"7.1","s":"Third source"}}'::jsonb;
  perform public.save_slack_proposal('verify-org',armed);
  perform public.save_slack_proposal('verify-org',blocked);
  perform public.save_slack_proposal('verify-org',third);
  op := public.reserve_slack_operation('verify-org',(armed->>'id')::uuid,1,'ffffffff-ffff-5fff-8fff-ffffffffffff','overlap-title','UMAYA');
  perform public.advance_slack_operation('verify-org',(op->>'id')::uuid,'reserved','{"state":"creating"}');
  insert into public.slack_claims(org_id,key) values ('verify-org','track:CBLOCKED:6.1');
  perform public.reserve_slack_operation('verify-org',(blocked->>'id')::uuid,1,'12121212-1212-5121-8121-121212121212','overlap-title','UMAYA');
  perform public.advance_slack_operation('verify-org',(op->>'id')::uuid,'creating','{"state":"refused"}');
  armed := armed || '{"revision":2,"suggestion":{"t":"Revised overlapping quota","a":"UMAYA","p":"DB","c":"CARMED","ts":"5.1","s":"Armed source"}}'::jsonb;
  if not public.save_slack_proposal('verify-org',armed,1) then raise exception 'refused owner cannot edit'; end if;
  op := public.reserve_slack_operation('verify-org',(third->>'id')::uuid,1,'13131313-1313-5131-8131-131313131313','overlap-title','UMAYA');
  if op->>'state'<>'uncertain' then raise exception 'overlapping legacy source fence was lost'; end if;
  raise notice 'Slack migration behavioral assertions passed';
end $verify$;
rollback;
